export const LAB_BY_CODE = Object.fromEntries(LAB_COURSES.map((c) => [c.code, c]));
export const LAB_BY_SLUG = Object.fromEntries(LAB_COURSES.map((c) => [c.slug, c]));
export const LAB_BY_TRACK = LAB_COURSES.reduce((acc, c) => {
  (acc[c.track_id] ||= []).push(c);
  return acc;
}, {});

export function getLabCourseBySlug(slug) {
  return LAB_BY_SLUG[slug] || null;
}

export function getLabCourseByCode(code) {
  return LAB_BY_CODE[code] || null;
}

export function getLabCoursesByTrack(trackId) {
  return LAB_BY_TRACK[trackId] || [];
}
